import matplotlib.pyplot as plt

def plot_3d_points_as_2d(points_3d):
    # z는 무시하고 x, y만 꺼내기
    xy_points = [(p[0], p[1]) for p in points_3d]

    # x, y 좌표 분리
    x_vals = [p[0] for p in xy_points]
    y_vals = [p[1] for p in xy_points]

    # 시각화
    plt.figure(figsize=(10, 8))
    plt.plot(x_vals, y_vals, 'o-', label='Path')  # 점과 선을 함께
    plt.title("2D Visualization of Given Points")
    plt.xlabel("X coordinate")
    plt.ylabel("Y coordinate")
    plt.grid(True)
    plt.legend()
    plt.axis('equal')
    plt.show()

